import type { Question } from "../../types";

export const B_AUTHORED_05: Question[] = [
  { id: "B-AUTH-161", section: "B", topic: "Assessment", subtopic: "pain scale", difficulty: "foundational", text: "A numeric pain rating is most useful when it is:", options: ["Anchored to the athlete's activity, function and agreed meaning", "Treated as a universal tissue-damage meter", "Collected without asking about function", "Used to overrule every other finding"], correct: 0, explanation: "Pain ratings are subjective and context-dependent; consistent anchors and functional context improve their usefulness.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-162", section: "B", topic: "Assessment", subtopic: "range of motion", difficulty: "applied", text: "A reduction in active range with near-normal passive range may indicate a need to examine:", options: ["Strength, pain inhibition, motor control and neurological status", "Only bone length", "Only skin temperature", "No further information"], correct: 0, explanation: "The difference between active and passive movement can guide hypotheses about force, pain, control and neural factors.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-163", section: "B", topic: "Assessment", subtopic: "resisted testing", difficulty: "foundational", text: "Resisted muscle testing provides information primarily about:", options: ["Force production, pain response and task-specific capacity", "The exact histological lesion", "Bone mineral density", "Future performance with certainty"], correct: 0, explanation: "Resisted testing can inform strength and symptom behaviour, but interpretation depends on position, effort, pain and test reliability.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-164", section: "B", topic: "Assessment", subtopic: "functional testing", difficulty: "analytical", text: "A rehabilitation test should be selected primarily according to:", options: ["The decision it must inform and the athlete's sport demands", "What is easiest to administer regardless of purpose", "The coach's favourite exercise", "The athlete's body mass alone"], correct: 0, explanation: "Tests have value when they are relevant, safe, reliable enough and linked to a clinical or performance decision.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-165", section: "B", topic: "Assessment", subtopic: "baseline", difficulty: "applied", text: "Why can a pre-season baseline be misleading if collected during pain or unusual fatigue?", options: ["It may not represent the athlete's healthy capacity and can distort later comparisons", "Baseline data are always invalid", "Fatigue improves all tests", "Pain never changes performance"], correct: 0, explanation: "Baseline conditions should be documented; a compromised baseline may not be an appropriate reference for injury or readiness decisions.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "B-AUTH-166", section: "B", topic: "Assessment", subtopic: "retest timing", difficulty: "analytical", text: "A strength test is repeated one hour after a fatiguing session. What is the main concern?", options: ["Fatigue may reduce reliability and obscure true capacity", "The second test is always more valid", "Testing fatigue has no effect", "The athlete's height may change"], correct: 0, explanation: "Testing conditions influence results. Fatigue, learning and recovery should be controlled or acknowledged.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "B-AUTH-167", section: "B", topic: "Assessment", subtopic: "clinical hypothesis", difficulty: "analytical", text: "Which sequence best represents sound clinical reasoning?", options: ["History, hypotheses, examination, interpretation, plan and reassessment", "Treatment first, history later", "Imaging alone, then clearance", "One test, one diagnosis, no review"], correct: 0, explanation: "Clinical reasoning is iterative: findings update hypotheses, and response to intervention informs the next decision.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-168", section: "B", topic: "Assessment", subtopic: "red flag escalation", difficulty: "analytical", text: "An athlete has unexplained weight loss, night sweats and persistent bone pain. What is the priority?", options: ["Urgent medical referral rather than routine sports rehabilitation", "A heavier strength programme", "Return-to-play testing", "A passive heat treatment"], correct: 0, explanation: "Systemic symptoms and unexplained persistent pain are red flags requiring medical assessment.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-169", section: "B", topic: "Assessment", subtopic: "neurovascular screen", difficulty: "foundational", text: "A neurovascular screen may include assessment of:", options: ["Sensation, motor function, pulses and relevant vascular signs", "Only flexibility", "Only body mass", "Only pain during exercise"], correct: 0, explanation: "Neurovascular screening helps identify nerve or circulation concerns that may alter urgency and referral.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-170", section: "B", topic: "Assessment", subtopic: "compartment syndrome", difficulty: "analytical", text: "Severe escalating limb pain, pain with passive stretch and neurological changes after trauma should prompt:", options: ["Emergency medical assessment for possible compartment syndrome", "Routine stretching", "A return-to-play test", "Delayed review after the tournament"], correct: 0, explanation: "This combination can indicate a limb-threatening emergency and requires urgent escalation.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-171", section: "B", topic: "Neck injury", subtopic: "cervical trauma", difficulty: "analytical", text: "After a collision, an athlete has neck pain and tingling in both hands. What should happen?", options: ["Protect the athlete and arrange urgent medical assessment", "Encourage rotation to test range", "Clear the athlete if strength seems normal", "Apply vigorous massage"], correct: 0, explanation: "Neurological symptoms after cervical trauma require protection and urgent assessment rather than field testing or return.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-172", section: "B", topic: "Neck injury", subtopic: "whiplash", difficulty: "applied", text: "A collision athlete has neck pain without neurological signs. Which initial management is most reasonable?", options: ["Assessment, education and graded activity matched to symptoms", "Prolonged immobilisation for every case", "Maximal contact practice", "No monitoring because there are no neurological signs"], correct: 0, explanation: "The absence of neurological signs does not eliminate the need for assessment, but uncomplicated presentations can often progress with education and activity.", source: "Kisner and Colby, Therapeutic Exercise", sourceId: "kisner-therapeutic-exercise", sourceKind: "textbook" },
  { id: "B-AUTH-173", section: "B", topic: "Head injury", subtopic: "concussion differential", difficulty: "analytical", text: "A player has a head impact followed by worsening headache and repeated vomiting. The priority is:", options: ["Urgent medical assessment for a potentially serious head injury", "A quiet return to the field", "A maximal balance test", "A routine next-week appointment"], correct: 0, explanation: "Worsening headache and repeated vomiting after head trauma are concerning features requiring urgent medical care.", source: "Amsterdam 2022 concussion consensus", sourceId: "ioc-concussion-amsterdam-2022", sourceKind: "consensus" },
  { id: "B-AUTH-174", section: "B", topic: "Thoracic injury", subtopic: "rib trauma", difficulty: "applied", text: "After a blow to the ribs, an athlete has increasing breathlessness and chest pain. What is the priority?", options: ["Stop activity and arrange urgent medical assessment", "Tape the ribs tightly and continue", "Test maximal trunk rotation", "Ignore the symptom if the score is close"], correct: 0, explanation: "Breathlessness and chest pain after trauma may indicate serious injury and require medical evaluation.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-175", section: "B", topic: "Shoulder injury", subtopic: "dislocation", difficulty: "foundational", text: "A visibly deformed shoulder after trauma should be:", options: ["Immobilised in a comfortable position and referred for urgent medical care", "Reduced on the field by an untrained person", "Tested through full range", "Returned to play if pain falls"], correct: 0, explanation: "Suspected dislocation requires protection and medical management; untrained reduction or testing can cause harm.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-176", section: "B", topic: "Shoulder injury", subtopic: "acromioclavicular injury", difficulty: "applied", text: "A rugby player lands on the shoulder and develops a local step deformity. What should be considered?", options: ["Acromioclavicular injury requiring assessment and appropriate protection", "A routine muscle cramp", "An isolated ankle sprain", "Immediate heavy pressing"], correct: 0, explanation: "Direct shoulder impact and a step deformity suggest AC-joint injury; severity and associated injury require assessment.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-177", section: "B", topic: "Shoulder rehabilitation", subtopic: "closed-chain control", difficulty: "applied", text: "A controlled wall push-up is used early after shoulder injury because it can:", options: ["Provide graded closed-chain loading with a manageable range and force", "Guarantee stability under contact", "Replace all overhead exposure", "Test maximal power"], correct: 0, explanation: "Closed-chain tasks can be scaled through angle, load and range to build control before more demanding activities.", source: "Kisner and Colby, Therapeutic Exercise", sourceId: "kisner-therapeutic-exercise", sourceKind: "textbook" },
  { id: "B-AUTH-178", section: "B", topic: "Shoulder rehabilitation", subtopic: "overhead progression", difficulty: "analytical", text: "A swimmer's shoulder programme progresses from supported elevation to resisted overhead work. Which principle is being applied?", options: ["A graded increase in task-specific load and control demand", "A move from active to complete rest", "A replacement of strength with passive motion", "A universal protocol independent of symptoms"], correct: 0, explanation: "Progression changes the mechanical and functional demand while monitoring symptoms and movement quality.", source: "Kisner and Colby, Therapeutic Exercise", sourceId: "kisner-therapeutic-exercise", sourceKind: "textbook" },
  { id: "B-AUTH-179", section: "B", topic: "Elbow injury", subtopic: "olecranon trauma", difficulty: "analytical", text: "After a fall, an athlete cannot actively extend the elbow and has marked swelling. What is the safest response?", options: ["Protect the elbow and arrange medical assessment", "Apply maximal resistance testing", "Continue throwing", "Assume simple soreness"], correct: 0, explanation: "Loss of active extension and swelling after trauma may indicate significant injury and requires evaluation.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-180", section: "B", topic: "Elbow rehabilitation", subtopic: "throwing load", difficulty: "applied", text: "A baseball pitcher develops elbow soreness only after high pitch counts. Which plan is most appropriate?", options: ["Review throwing volume and mechanics while restoring capacity with a graded return", "Increase pitch count to build tolerance", "Treat only the forearm with massage", "Ignore the exposure because soreness is expected"], correct: 0, explanation: "Throwing volume and intensity are central exposures. Rehabilitation must combine load management with strength and a staged throwing plan.", source: "Brukner and Khan's Clinical Sports Medicine", sourceKind: "textbook" },
  { id: "B-AUTH-181", section: "B", topic: "Wrist injury", subtopic: "distal radius", difficulty: "foundational", text: "A fall on the hand followed by deformity and severe wrist pain should prompt:", options: ["Immobilisation and urgent medical assessment", "Grip-strength testing", "Return to play in a brace without review", "Deep friction massage"], correct: 0, explanation: "Deformity after trauma is a possible fracture or dislocation and needs protection and medical assessment.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-182", section: "B", topic: "Wrist rehabilitation", subtopic: "loading", difficulty: "applied", text: "After a healed wrist injury, loading should be progressed according to:", options: ["Pain, range, strength, grip function and the demands of the sport", "Only the date of the cast removal", "A universal weight for every athlete", "The athlete's height"], correct: 0, explanation: "Progression should reflect recovered capacity and task demands, with symptoms and function guiding the dose.", source: "Kisner and Colby, Therapeutic Exercise", sourceId: "kisner-therapeutic-exercise", sourceKind: "textbook" },
  { id: "B-AUTH-183", section: "B", topic: "Hand injury", subtopic: "tendon injury", difficulty: "analytical", text: "After a finger laceration, an athlete cannot flex the distal interphalangeal joint. What is required?", options: ["Prompt specialist medical assessment for possible flexor tendon injury", "Maximal resisted flexion", "Return to climbing", "Routine stretching only"], correct: 0, explanation: "Loss of specific tendon function after laceration requires timely specialist assessment and protection.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-184", section: "B", topic: "Hand injury", subtopic: "splinting", difficulty: "applied", text: "A splint prescription should be reviewed because it can affect:", options: ["Tissue protection, range, skin integrity, function and adherence", "Only the athlete's motivation", "The diagnosis with certainty", "No aspect of rehabilitation"], correct: 0, explanation: "Splints have benefits and risks. Fit, skin, movement, function and adherence should be monitored and adjusted.", source: "Kisner and Colby, Therapeutic Exercise", sourceId: "kisner-therapeutic-exercise", sourceKind: "textbook" },
  { id: "B-AUTH-185", section: "B", topic: "Hip injury", subtopic: "labral symptoms", difficulty: "analytical", text: "An athlete describes clicking, catching and deep hip pain during pivoting. What is appropriate?", options: ["Clinical assessment and referral if indicated rather than a definitive label from symptoms alone", "Immediate maximal pivoting", "Only hamstring stretching", "No further assessment because clicking is harmless"], correct: 0, explanation: "Mechanical symptoms may warrant further assessment, but they do not establish a specific structural lesion without appropriate evaluation.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-186", section: "B", topic: "Hip rehabilitation", subtopic: "single-leg control", difficulty: "applied", text: "A runner demonstrates pelvic drop during single-leg stance. Which rehabilitation domain is relevant?", options: ["Hip abductor capacity, trunk control and task-specific single-leg loading", "Only ankle flexibility", "Only upper-limb endurance", "Avoiding all running permanently"], correct: 0, explanation: "Pelvic control reflects coordinated strength and motor control; progression should connect exercises to running demands.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "B-AUTH-187", section: "B", topic: "Groin injury", subtopic: "adductor squeeze", difficulty: "applied", text: "An adductor squeeze test is best interpreted as:", options: ["One measure of pain and force response within the broader groin assessment", "A direct image of the tendon", "A guarantee of return readiness", "A substitute for history"], correct: 0, explanation: "Squeeze testing can provide useful symptom and capacity information but is not a complete diagnosis or clearance test.", source: "Brukner and Khan's Clinical Sports Medicine", sourceKind: "textbook" },
  { id: "B-AUTH-188", section: "B", topic: "Groin rehabilitation", subtopic: "change of direction", difficulty: "analytical", text: "A footballer tolerates straight-line running but pain returns with cutting. What should be progressed next?", options: ["Planned then reactive change-of-direction exposure with appropriate adductor capacity", "More straight-line volume only", "Immediate full match", "No lower-limb exercise"], correct: 0, explanation: "Cutting adds frontal and transverse-plane demands; graded exposure should match the task that provokes symptoms.", source: "Brukner and Khan's Clinical Sports Medicine", sourceKind: "textbook" },
  { id: "B-AUTH-189", section: "B", topic: "Knee injury", subtopic: "meniscal symptoms", difficulty: "analytical", text: "An athlete has true locking after a knee injury. What is the most appropriate action?", options: ["Arrange medical assessment for possible mechanical obstruction", "Force the knee through repeated flexion", "Clear the athlete if jogging is painless", "Use only ice"], correct: 0, explanation: "True locking can indicate a mechanical problem requiring assessment and should not be repeatedly forced.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-190", section: "B", topic: "Knee injury", subtopic: "swelling", difficulty: "foundational", text: "An acute knee effusion after a twisting injury should lead the clinician to:", options: ["Examine the injury and consider internal derangement or fracture before progression", "Assume simple soreness", "Begin maximal jumping", "Ignore the timing of swelling"], correct: 0, explanation: "Rapid swelling after trauma can be clinically significant and should inform examination and referral decisions.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-191", section: "B", topic: "Knee rehabilitation", subtopic: "open-chain exercise", difficulty: "applied", text: "An open-chain knee extension exercise may be useful when the goal is to:", options: ["Target quadriceps capacity with a controllable range and load", "Avoid all quadriceps activation", "Replace every functional task", "Guarantee ligament healing"], correct: 0, explanation: "Open-chain exercise can target a muscle and be dosed precisely; its range and load should match the clinical stage and goal.", source: "Kisner and Colby, Therapeutic Exercise", sourceId: "kisner-therapeutic-exercise", sourceKind: "textbook" },
  { id: "B-AUTH-192", section: "B", topic: "Knee rehabilitation", subtopic: "squat progression", difficulty: "applied", text: "A squat progression is advanced when the athlete demonstrates:", options: ["Appropriate control, tolerable symptoms and capacity for the next task demand", "A fixed number of calendar days", "The deepest possible range regardless of pain", "A perfect comparison with a teammate"], correct: 0, explanation: "Criteria such as movement quality, symptoms, load and recovery are more informative than time alone.", source: "Kisner and Colby, Therapeutic Exercise", sourceId: "kisner-therapeutic-exercise", sourceKind: "textbook" },
  { id: "B-AUTH-193", section: "B", topic: "Lower-limb rehabilitation", subtopic: "landing", difficulty: "analytical", text: "An athlete lands stiffly with high audible impact but no pain. What should the team do?", options: ["Assess the strategy and progressively train landing absorption rather than diagnose injury from sound", "Ban all jumping", "Ignore it completely", "Declare the athlete unsafe from one repetition"], correct: 0, explanation: "Landing strategy is a modifiable performance finding; it should be assessed across repetitions, fatigue and sport context.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "B-AUTH-194", section: "B", topic: "Lower-limb rehabilitation", subtopic: "deceleration", difficulty: "applied", text: "Why should deceleration be trained separately before unrestricted cutting in some athletes?", options: ["It requires rapid force absorption and control that may exceed straight-line running", "Deceleration never occurs in sport", "It is only an upper-limb skill", "It guarantees no future injury"], correct: 0, explanation: "Braking and redirection create high mechanical and perceptual demands; they can be progressed deliberately before chaotic sport exposure.", source: "Neumann, Kinesiology of the Musculoskeletal System", sourceId: "neumann-kinesiology", sourceKind: "textbook" },
  { id: "B-AUTH-195", section: "B", topic: "Lower-limb rehabilitation", subtopic: "reactive drills", difficulty: "analytical", text: "A reactive drill is more demanding than a planned drill because it adds:", options: ["Decision-making and unpredictable timing or direction", "Less cognitive demand", "No movement variability", "Only seated effort"], correct: 0, explanation: "Reactive tasks combine physical movement with perception and decision-making, so they should be introduced as capacity develops.", source: "Kisner and Colby, Therapeutic Exercise", sourceId: "kisner-therapeutic-exercise", sourceKind: "textbook" },
  { id: "B-AUTH-196", section: "B", topic: "Lower-limb rehabilitation", subtopic: "fatigue", difficulty: "analytical", text: "Movement quality deteriorates only after ten repeated jumps. What does this support?", options: ["Including fatigue-state testing or exposure before declaring full readiness", "Testing one fresh jump only", "Removing all jump training", "Ignoring fatigue because the first jump was good"], correct: 0, explanation: "Sport often occurs under fatigue. Testing and training should consider the conditions in which control is challenged.", source: "Bern return-to-sport consensus", sourceKind: "consensus" },
  { id: "B-AUTH-197", section: "B", topic: "Rehabilitation planning", subtopic: "criteria", difficulty: "foundational", text: "A criteria-based rehabilitation plan progresses when:", options: ["The athlete meets agreed clinical, functional and load-tolerance criteria", "The calendar reaches a fixed date", "The coach becomes impatient", "All symptoms must be absent from every activity"], correct: 0, explanation: "Criteria-based progression uses relevant measures and response rather than relying only on time or unrealistic symptom elimination.", source: "Kisner and Colby, Therapeutic Exercise", sourceId: "kisner-therapeutic-exercise", sourceKind: "textbook" },
  { id: "B-AUTH-198", section: "B", topic: "Rehabilitation planning", subtopic: "regression", difficulty: "applied", text: "A planned regression in exercise difficulty should be described as:", options: ["An adjustment to keep the stimulus within current capacity", "Proof that the athlete failed", "A permanent loss of fitness", "A reason to stop all movement"], correct: 0, explanation: "Regression is a normal load-management tool when symptoms, quality or recovery show that the current step is too demanding.", source: "Kisner and Colby, Therapeutic Exercise", sourceId: "kisner-therapeutic-exercise", sourceKind: "textbook" },
  { id: "B-AUTH-199", section: "B", topic: "Rehabilitation planning", subtopic: "home exercise", difficulty: "applied", text: "An athlete does not complete a home programme because it takes 45 minutes. What should happen first?", options: ["Explore barriers and redesign a shorter, meaningful programme", "Double the prescription", "Label the athlete unmotivated", "Stop physiotherapy"], correct: 0, explanation: "Programme burden is a modifiable barrier. Collaborative redesign can improve adherence without blaming the athlete.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "B-AUTH-200", section: "B", topic: "Rehabilitation planning", subtopic: "education", difficulty: "foundational", text: "An effective exercise explanation should include:", options: ["The purpose, dosage, expected response and when to modify or seek help", "Only the exercise name", "A promise of a cure", "No opportunity for questions"], correct: 0, explanation: "Education supports safe self-management when the athlete understands why, how much, what to expect and what to do if symptoms change.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "B-AUTH-201", section: "B", topic: "Rehabilitation planning", subtopic: "dose response", difficulty: "analytical", text: "The same exercise dose produces different responses on two weeks. What should the clinician consider?", options: ["Sleep, stress, preceding load, symptoms, technique and recovery context", "Only the exercise name", "That physiology never varies", "A need to double the dose automatically"], correct: 0, explanation: "Response is influenced by the whole training and health context; dose should be interpreted longitudinally and individually.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "B-AUTH-202", section: "B", topic: "Rehabilitation planning", subtopic: "cross-training", difficulty: "applied", text: "Cross-training during rehabilitation is useful when it:", options: ["Maintains relevant conditioning without exceeding the injured tissue's current tolerance", "Adds maximal load to the injured tissue", "Replaces all eventual sport exposure", "Ignores symptoms"], correct: 0, explanation: "Alternative modes can preserve conditioning while the injured tissue is progressively loaded in an appropriate manner.", source: "Kisner and Colby, Therapeutic Exercise", sourceId: "kisner-therapeutic-exercise", sourceKind: "textbook" },
  { id: "B-AUTH-203", section: "B", topic: "Rehabilitation planning", subtopic: "pool exercise", difficulty: "foundational", text: "Aquatic exercise may reduce land-based loading because:", options: ["Buoyancy reduces effective weight-bearing while allowing movement practice", "Water eliminates all cardiovascular demand", "It guarantees tissue healing", "It cannot be progressed"], correct: 0, explanation: "Buoyancy changes loading and can support early movement, but exercise intensity and safety still need individual prescription.", source: "Kisner and Colby, Therapeutic Exercise", sourceId: "kisner-therapeutic-exercise", sourceKind: "textbook" },
  { id: "B-AUTH-204", section: "B", topic: "Rehabilitation planning", subtopic: "isokinetic testing", difficulty: "analytical", text: "An isokinetic test can be useful but should not be treated as:", options: ["A complete substitute for sport-specific function and decision-making", "A controlled strength measure", "One source of capacity information", "A test requiring protocol documentation"], correct: 0, explanation: "Isokinetic data can inform torque and asymmetry under controlled conditions but do not reproduce every sport demand.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-205", section: "B", topic: "Rehabilitation planning", subtopic: "manual strength test", difficulty: "foundational", text: "A manual muscle test may be limited in strong athletes because:", options: ["The examiner may not provide enough resistance to distinguish higher force levels", "It always measures too much force", "It directly measures power", "It is unaffected by examiner skill"], correct: 0, explanation: "Manual testing can have a ceiling and examiner-dependence, so stronger athletes may need more objective or task-specific measures.", source: "Magee, Orthopedic Physical Assessment", sourceId: "magee-orthopaedic-assessment", sourceKind: "textbook" },
  { id: "B-AUTH-206", section: "B", topic: "Rehabilitation planning", subtopic: "force plate", difficulty: "applied", text: "A force-plate asymmetry should be interpreted with:", options: ["Task instructions, phase of movement, reliability and the athlete's symptoms and goals", "A universal injury threshold", "Only body mass", "No repeat testing"], correct: 0, explanation: "Force-plate outputs are task-specific and should be interpreted using reliable measures and the decision context.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "B-AUTH-207", section: "B", topic: "Rehabilitation planning", subtopic: "return metrics", difficulty: "analytical", text: "A return-to-sport battery contains ten tests but no match-exposure measure. What is its main gap?", options: ["It may not establish tolerance of the actual sport workload", "More isolated tests are always needed", "Match exposure is never relevant", "It proves the battery is invalid"], correct: 0, explanation: "Sport return includes repeated exposure, fatigue and decision demands; isolated tests should be supplemented by progressive participation.", source: "Bern return-to-sport consensus", sourceKind: "consensus" },
  { id: "B-AUTH-208", section: "B", topic: "Rehabilitation planning", subtopic: "performance level", difficulty: "analytical", text: "An athlete returns to competition but is not at pre-injury performance. The correct description is:", options: ["Return to sport may have occurred, while return to performance remains in progress", "The rehabilitation has necessarily failed", "Competition proves full recovery", "Performance is unrelated to rehabilitation"], correct: 0, explanation: "Participation and performance are distinct stages; workload and performance capacity can continue to develop after competition resumes.", source: "Bern return-to-sport consensus", sourceKind: "consensus" },
  { id: "B-AUTH-209", section: "B", topic: "Rehabilitation planning", subtopic: "monitoring", difficulty: "foundational", text: "A useful rehabilitation monitoring plan should specify:", options: ["What is measured, when, by whom, how it changes decisions and when to review", "Only the final goal", "No thresholds or review points", "A single subjective score"], correct: 0, explanation: "Monitoring is actionable when variables, timing, decision rules and review points are explicit.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "B-AUTH-210", section: "B", topic: "Rehabilitation planning", subtopic: "athlete feedback", difficulty: "applied", text: "An athlete reports that an exercise feels unsafe despite acceptable pain. What should the clinician do?", options: ["Explore the concern, observe the task and adapt education or progression", "Dismiss it because pain is low", "Force the exercise", "Remove all exercise"], correct: 0, explanation: "Perceived safety and confidence influence participation. The clinician should investigate and adapt the plan collaboratively.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "B-AUTH-211", section: "B", topic: "Injury prevention", subtopic: "warm-up programme", difficulty: "applied", text: "A team prevention warm-up is most likely to be effective when it is:", options: ["Consistently delivered, sport-relevant and monitored for adherence", "Performed once before selection", "Unrelated to the sport", "Optional only after injury"], correct: 0, explanation: "Prevention programmes depend on appropriate content and regular adherence rather than one-time screening or exposure.", source: "IOC consensus statement on injury surveillance", sourceId: "ioc-injury-surveillance-2020", sourceKind: "consensus" },
  { id: "B-AUTH-212", section: "B", topic: "Injury prevention", subtopic: "risk factors", difficulty: "analytical", text: "A risk factor identified in a group should not be presented to an individual athlete as:", options: ["A certain prediction that injury will occur", "One part of a multifactorial assessment", "A prompt for targeted prevention", "A variable needing contextual interpretation"], correct: 0, explanation: "Group associations do not provide deterministic individual predictions; risk information should support, not replace, clinical judgement.", source: "IOC consensus statement on injury surveillance", sourceId: "ioc-injury-surveillance-2020", sourceKind: "consensus" },
  { id: "B-AUTH-213", section: "B", topic: "Injury prevention", subtopic: "screening", difficulty: "analytical", text: "A screening test identifies many athletes as high risk but does not improve outcomes when used alone. What is the lesson?", options: ["Screening must connect to effective, feasible prevention and appropriate follow-up", "More screening is always better", "The test predicts every injury", "All athletes should be excluded"], correct: 0, explanation: "Screening has value only when it informs a beneficial action and the test's accuracy and consequences are understood.", source: "IOC consensus statement on injury surveillance", sourceId: "ioc-injury-surveillance-2020", sourceKind: "consensus" },
  { id: "B-AUTH-214", section: "B", topic: "Injury prevention", subtopic: "load capacity", difficulty: "foundational", text: "A prevention plan should balance exposure with:", options: ["The athlete's current capacity, recovery and adaptation", "Only the next fixture", "A fixed team average", "The belief that rest is always harmful"], correct: 0, explanation: "Injury prevention involves building capacity and managing exposure and recovery rather than eliminating all loading.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "B-AUTH-215", section: "B", topic: "Injury prevention", subtopic: "recovery", difficulty: "applied", text: "A team with dense competition has rising soreness and declining sleep. Which intervention is most logical?", options: ["Review scheduling, recovery resources and load distribution with the athlete and staff", "Add extra conditioning daily", "Ignore the pattern until injury occurs", "Use a single supplement for everyone"], correct: 0, explanation: "Recovery problems should prompt a systems review of load, travel, sleep and resources rather than a single universal intervention.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "B-AUTH-216", section: "B", topic: "Injury prevention", subtopic: "injury audit", difficulty: "applied", text: "An injury audit is most useful when it leads to:", options: ["A specific change, responsible owner, implementation and re-measurement", "A list of injuries with no action", "Blame without system review", "A permanent ban on the sport"], correct: 0, explanation: "Audit becomes improvement when findings are translated into a monitored change and reviewed for effect.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "B-AUTH-217", section: "B", topic: "Emergency care", subtopic: "cardiac arrest", difficulty: "foundational", text: "If an athlete is unresponsive and not breathing normally, the team should:", options: ["Activate emergency response and begin CPR and AED procedures according to training", "Wait for a physician without action", "Give oral fluids", "Place the athlete in a stretching position"], correct: 0, explanation: "Early emergency activation, CPR and AED use according to local training are critical in suspected cardiac arrest.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "B-AUTH-218", section: "B", topic: "Emergency care", subtopic: "spinal precautions", difficulty: "analytical", text: "After a collision, an athlete has severe neck pain but is alert. The team should:", options: ["Stabilise and follow the emergency spinal-injury protocol", "Ask the athlete to walk off", "Perform neck manipulation", "Resume play after a few minutes"], correct: 0, explanation: "Potential spinal injury requires protection, minimal unnecessary movement and trained emergency assessment.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "B-AUTH-219", section: "B", topic: "Emergency care", subtopic: "anaphylaxis", difficulty: "analytical", text: "An athlete develops breathing difficulty, wheeze and facial swelling after a food exposure. What is the priority?", options: ["Activate emergency care and use the athlete's prescribed emergency medication if trained and available", "Continue warm-up", "Offer only water", "Wait for symptoms to settle"], correct: 0, explanation: "The presentation may be anaphylaxis, a medical emergency requiring immediate emergency activation and appropriate medication according to protocol.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "B-AUTH-220", section: "B", topic: "Emergency care", subtopic: "hypoglycaemia", difficulty: "applied", text: "A conscious athlete with diabetes is confused, sweaty and able to swallow. The immediate response should follow:", options: ["The athlete's diabetes emergency plan and appropriate rapid carbohydrate treatment", "A maximal sprint", "A high-protein meal only", "No intervention"], correct: 0, explanation: "Suspected hypoglycaemia needs prompt protocol-based management and medical escalation when necessary; individual plans should guide care.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "B-AUTH-221", section: "B", topic: "Emergency care", subtopic: "heat cramps", difficulty: "foundational", text: "A cramping athlete in the heat should first be assessed for:", options: ["Severity, mental status, heat illness signs and need for medical escalation", "Only calf flexibility", "A return-to-play score", "Whether the athlete can sprint"], correct: 0, explanation: "Cramps can coexist with serious heat illness. The initial assessment must not assume a benign isolated muscle problem.", source: "NATA Position Statement: Exertional Heat Illness", sourceKind: "guideline" },
  { id: "B-AUTH-222", section: "B", topic: "Emergency care", subtopic: "cooling", difficulty: "analytical", text: "For suspected exertional heat stroke, cooling should:", options: ["Begin immediately while emergency care is activated", "Wait until a specialist arrives", "Be replaced by stretching", "Start only after the athlete reaches the hospital"], correct: 0, explanation: "Rapid cooling is time-critical and should occur alongside emergency activation according to the venue protocol.", source: "NATA Position Statement: Exertional Heat Illness", sourceKind: "guideline" },
  { id: "B-AUTH-223", section: "B", topic: "Emergency care", subtopic: "bleeding control", difficulty: "foundational", text: "When direct pressure controls a wound, the dressing should generally be:", options: ["Left in place and reinforced if needed while following first-aid protocol", "Removed repeatedly to inspect every minute", "Covered with ice only", "Used as a reason to return to play"], correct: 0, explanation: "Maintaining pressure supports bleeding control; severe bleeding still requires emergency care and appropriate wound management.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "B-AUTH-224", section: "B", topic: "Emergency care", subtopic: "infection control", difficulty: "foundational", text: "Standard precautions in sports first aid include:", options: ["Hand hygiene, appropriate gloves and safe handling of blood or bodily fluids", "Sharing used dressings", "Touching blood without protection", "Ignoring equipment cleaning"], correct: 0, explanation: "Standard precautions protect athletes and staff and reduce transmission risk during first aid and clinical care.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
  { id: "B-AUTH-225", section: "B", topic: "Emergency care", subtopic: "emergency equipment", difficulty: "applied", text: "An emergency kit should be checked before an event for:", options: ["Availability, expiry, function, accessibility and staff familiarity", "Only its colour", "Whether it was used last season", "No reason because equipment never expires"], correct: 0, explanation: "Equipment readiness depends on stock, expiry, function, access and trained use before an emergency occurs.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "B-AUTH-226", section: "B", topic: "Emergency care", subtopic: "handover", difficulty: "applied", text: "A useful emergency handover should include:", options: ["Mechanism, observed signs, vital actions, response, medications and timing", "Only the athlete's name", "A speculative diagnosis without observations", "The match result only"], correct: 0, explanation: "Structured handover transfers essential facts, actions and timing so receiving clinicians can continue safe care.", source: "SAI High Performance Analyst role duties", sourceId: "sai-hpa-advertisement-2023", sourceKind: "official" },
  { id: "B-AUTH-227", section: "B", topic: "Infection and illness", subtopic: "return after infection", difficulty: "analytical", text: "A player has fever and systemic symptoms during a tournament. The appropriate advice is to:", options: ["Stop training and obtain medical assessment with infection-control consideration", "Train through the fever", "Share bottles to maintain hydration", "Use antibiotics without prescription"], correct: 0, explanation: "Fever and systemic illness require medical review, rest from strenuous activity and measures to reduce transmission.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "B-AUTH-228", section: "B", topic: "Infection and illness", subtopic: "respiratory symptoms", difficulty: "applied", text: "An athlete recovering from a respiratory infection develops chest tightness during easy exercise. What should happen?", options: ["Stop exercise and seek medical review", "Increase intensity", "Assume normal deconditioning", "Clear the athlete because fever is absent"], correct: 0, explanation: "Chest symptoms during exercise after illness warrant caution and medical assessment rather than continued progression.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "B-AUTH-229", section: "B", topic: "Infection and illness", subtopic: "return progression", difficulty: "foundational", text: "A graded return after illness should increase load only when:", options: ["Symptoms and physiological response remain acceptable at the current step", "The calendar requires full training", "The athlete feels impatient", "All monitoring is stopped"], correct: 0, explanation: "Progression should be symptom- and response-guided, with medical oversight when indicated.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "B-AUTH-230", section: "B", topic: "Infection and illness", subtopic: "team policy", difficulty: "analytical", text: "A team illness policy should include:", options: ["Reporting, isolation or modification guidance, medical review and return criteria", "Only a punishment for disclosure", "No communication plan", "A rule to train through all symptoms"], correct: 0, explanation: "Clear policies support early reporting, infection control, appropriate care and safe return while reducing pressure to hide illness.", source: "IOC consensus statement on load and illness", sourceId: "ioc-load-illness-2016", sourceKind: "consensus" },
  { id: "B-AUTH-231", section: "B", topic: "Female athlete health", subtopic: "screening conversation", difficulty: "foundational", text: "A conversation about menstrual health should be:", options: ["Private, respectful, non-judgmental and linked to appropriate care", "Conducted publicly in the team meeting", "Focused only on body weight", "Used to select athletes"], correct: 0, explanation: "Sensitive health information requires privacy, respectful language and clinical referral when concerns are identified.", source: "IOC consensus statement on REDs: 2023 update", sourceId: "ioc-reds-2023", sourceKind: "consensus" },
  { id: "B-AUTH-232", section: "B", topic: "Female athlete health", subtopic: "energy availability", difficulty: "applied", text: "Energy availability is most concerned with energy remaining for physiological function after accounting for:", options: ["Exercise expenditure", "Only protein intake", "Only sleep duration", "Only body height"], correct: 0, explanation: "Energy availability considers intake relative to exercise expenditure and body size, with consequences for health and performance.", source: "IOC consensus statement on REDs: 2023 update", sourceId: "ioc-reds-2023", sourceKind: "consensus" },
  { id: "B-AUTH-233", section: "B", topic: "Female athlete health", subtopic: "bone stress", difficulty: "analytical", text: "A runner with repeated bone stress injuries should not simply be prescribed more impact because:", options: ["Bone health, energy availability, training load and medical factors must be assessed", "Impact always strengthens bone immediately", "Nutrition is irrelevant", "Symptoms are always imaginary"], correct: 0, explanation: "Repeated bone stress requires a broad assessment and staged loading that addresses health and mechanical risk factors.", source: "IOC consensus statement on REDs: 2023 update", sourceId: "ioc-reds-2023", sourceKind: "consensus" },
  { id: "B-AUTH-234", section: "B", topic: "Female athlete health", subtopic: "body image", difficulty: "analytical", text: "An athlete expresses fear of gaining weight and is restricting food despite fatigue. What is appropriate?", options: ["Use sensitive multidisciplinary referral and avoid weight-focused coercion", "Praise the restriction", "Increase training", "Make body mass public"], correct: 0, explanation: "Eating and body-image concerns require compassionate, confidential, multidisciplinary care rather than coercive performance pressure.", source: "IOC consensus statement on REDs: 2023 update", sourceId: "ioc-reds-2023", sourceKind: "consensus" },
  { id: "B-AUTH-235", section: "B", topic: "Nutrition", subtopic: "pre-exercise meal", difficulty: "foundational", text: "A pre-exercise nutrition plan should be individualised according to:", options: ["Timing, sport demands, tolerance, goals and gastrointestinal response", "A universal food for every athlete", "Only the athlete's height", "Whether teammates like the meal"], correct: 0, explanation: "Nutrition is practical and individual. Timing and composition should be trialled and adjusted to the athlete and task.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "B-AUTH-236", section: "B", topic: "Nutrition", subtopic: "recovery nutrition", difficulty: "applied", text: "Post-exercise recovery nutrition should support restoration of:", options: ["Fluid, carbohydrate and protein needs appropriate to the next training demand", "Only body mass", "Only caffeine", "No physiological process"], correct: 0, explanation: "Recovery needs depend on the next exposure, but fluids, carbohydrate and protein commonly contribute to restoration and adaptation.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "B-AUTH-237", section: "B", topic: "Nutrition", subtopic: "supplement counselling", difficulty: "analytical", text: "A supplement has a promising small study but uncertain contamination control. The safest advice is to:", options: ["Discuss uncertain benefit and risk, verify the product and consider alternatives", "Guarantee benefit", "Ignore anti-doping risk", "Use it without trial"], correct: 0, explanation: "Supplement decisions balance evidence, product quality, health and anti-doping risk; small studies do not guarantee individual benefit.", source: "WADA 2026 Prohibited List", sourceId: "wada-prohibited-list-2026", sourceKind: "official", asOf: "2026-08-12" },
  { id: "B-AUTH-238", section: "B", topic: "Nutrition", subtopic: "hydration monitoring", difficulty: "applied", text: "Which field measure can help estimate an athlete's sweat loss across a session?", options: ["Standardised pre- and post-session body mass with intake and urine recorded", "A single post-season BMI", "A flexibility score", "The athlete's shoe size"], correct: 0, explanation: "Mass change combined with fluid intake and urine output can estimate fluid loss when measurements are standardised.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "B-AUTH-239", section: "B", topic: "Nutrition", subtopic: "gastrointestinal tolerance", difficulty: "applied", text: "An athlete develops gastrointestinal distress after trying a new race nutrition product. What should be changed?", options: ["Trial dose, timing, composition and strategy during training before competition", "Increase the dose on race day", "Ignore the pattern", "Remove all food permanently"], correct: 0, explanation: "Race nutrition should be practised and individualised; product, dose and timing can all affect tolerance.", source: "ACSM Guidelines for Exercise Testing and Prescription", sourceId: "acsm-getp-12", sourceKind: "textbook" },
  { id: "B-AUTH-240", section: "B", topic: "Nutrition", subtopic: "professional referral", difficulty: "foundational", text: "A physiotherapist should refer an athlete for detailed medical nutrition therapy when:", options: ["The nutrition need exceeds the physiotherapist's competence or involves a health condition", "The athlete asks one hydration question", "The athlete eats carbohydrates", "No referral is ever needed"], correct: 0, explanation: "Working within competence includes timely collaboration with a sports dietitian or medical professional for specialised nutrition care.", source: "World Physiotherapy standards of physiotherapist practice", sourceId: "world-physiotherapy-standards-2025", sourceKind: "guideline" },
];
